import sys

def ispar(x):
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in x:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack:
                return False
            top = stack.pop()
            if mapping[char] != top:
                return False

    return len(stack) == 0

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    result = ispar(s)
    print(result)
